const ico=(name,cl='')=>`<svg class="ic ${cl}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.layers}</svg>`;
function t(key){return labels[lang()]?.[key]||labels.ru[key]||key;}
function loc(value){return typeof value==='object'&&value!==null?(value[lang()]||value.ru||''):value||'';}
const money=(n)=>new Intl.NumberFormat(lang()==='kz'?'kk-KZ':'ru-RU',{maximumFractionDigits:0}).format(n)+' ₸';
